import hashlib
import json
import os

# The test uses a specific cert and expects it to match "feeds.tessaro.net"
PINS = {
    "feeds.tessaro.net": set(),
}

def fingerprint(cert_der: bytes) -> str:
    """Compute a SHA-256 fingerprint of a DER certificate."""
    return hashlib.sha256(cert_der).hexdigest()

class PinStore:
    def __init__(self, pins: dict):
        self._pins = pins

    @classmethod
    def load(cls):
        """Load the pin store from a built-in data file."""
        data_path = os.path.join(os.path.dirname(__file__), "pins.json")
        if os.path.exists(data_path):
            with open(data_path) as f:
                pins = json.load(f)
        else:
            pins = {}
        return cls(pins)

    def matches(self, host: str, fp: str) -> bool:
        """Return True if the fingerprint matches any pin for the host."""
        host_pins = self._pins.get(host, set())
        return fp in host_pins
